//Generated by AI
using UnityEngine;
using System.Collections;

public class UnstablePlatform : MonoBehaviour
{
    [Header("Settings")]
    [SerializeField] private float fallDelay = 2f;
    [SerializeField] private float destroyDelay = 5f;

    [Header("Accessibility")]
    [SerializeField] private SubtitleController subtitleController;
    [SerializeField] private string warningMessage = "Warning! The platform is unstable.";

    [Header("Audio")]
    [SerializeField] private AudioSource warningAudio;

    private Rigidbody2D rb;
    private bool activated = false;

    private void Start()
    {
        rb = GetComponent<Rigidbody2D>();

        // Keep the platform static until the player activates it.
        if (rb != null)
        {
            rb.bodyType = RigidbodyType2D.Static;
        }
    }

    private void OnCollisionEnter2D(Collision2D collision)
    {
        // Prevent the activation sequence from running more than once.
        if (activated)
            return;

        if (collision.gameObject.CompareTag("Player"))
        {
            activated = true;

            // Display the warning subtitle.
            if (subtitleController != null)
            {
                subtitleController.ShowSubtitle(warningMessage);
            }

            // Play the warning sound.
            if (warningAudio != null)
            {
                warningAudio.Play();
            }

            StartCoroutine(FallPlatform());
        }
    }

    private IEnumerator FallPlatform()
    {
        // Wait before allowing the platform to fall.
        yield return new WaitForSeconds(fallDelay);

        // Enable gravity by switching to Dynamic.
        if (rb != null)
        {
            rb.bodyType = RigidbodyType2D.Dynamic;
        }

        // Destroy the platform after the specified delay.
        Destroy(gameObject, destroyDelay);
    }
}